// SPDX-License-Identifier: MIT
pragma solidity ^0.8.28;

import {ReentrancyGuard} from "@openzeppelin/contracts/utils/ReentrancyGuard.sol";
import {Ownable} from "@openzeppelin/contracts/access/Ownable.sol";
import {IERC20} from "@openzeppelin/contracts/token/ERC20/IERC20.sol";
import {SafeERC20} from "@openzeppelin/contracts/token/ERC20/utils/SafeERC20.sol";

contract BaseStrategy is Ownable, ReentrancyGuard {
    using SafeERC20 for IERC20;

    IERC20 public immutable underlying;
    address public keeper;
    address public vault; // authorized to recall funds for user withdrawals
    // slither-disable-next-line constable-states
    uint256 public totalDebt;
    bool public isActive;
    // slither-disable-next-line immutable-states
    uint256 public lastHarvest;
    mapping(address => uint256) public shares;
    string public name_;

    uint256 public constant MAX_WITHDRAWAL_FEE = 500;
    uint256 public constant MAX_PERFORMANCE_FEE = 10000;

    event Harvest(uint256 profit);
    event Deposit(address indexed user, uint256 amount);
    event Withdraw(address indexed user, uint256 amount);
    event KeeperSet(address indexed keeper);
    event ActiveChanged(bool active);

    constructor(address _underlying, address initialOwner, string memory _name) Ownable(initialOwner) {
        require(_underlying != address(0), "BaseStrategy: zero underlying");
        require(initialOwner != address(0), "BaseStrategy: zero owner");
        underlying = IERC20(_underlying);
        isActive = true;
        name_ = _name;
        lastHarvest = block.timestamp;
    }

    function name() external view virtual returns (string memory) {
        return name_;
    }

    function deposit(uint256 amount) external virtual nonReentrant {
        require(amount > 0, "BaseStrategy: zero amount");
        shares[msg.sender] += amount;
        underlying.safeTransferFrom(msg.sender, address(this), amount);
        emit Deposit(msg.sender, amount);
    }

    // NOTE: user-facing withdraw lives ONLY in ProYieldVault (1:1 shares +
    // strategy recall). The former BaseStrategy.withdraw here used broken
    // proportional share math (under-burned shares on partial withdrawals —
    // drain vector) and was removed so it can never be inherited again (T-012).

    function harvest() external virtual nonReentrant {
        require(isActive, "BaseStrategy: inactive");
        uint256 profit = _doHarvest();
        totalDebt += profit;
        lastHarvest = block.timestamp;
        emit Harvest(profit);
    }

    // slither-disable-next-line dead-code
    function _doHarvest() internal virtual returns (uint256) {
        return 0;
    }

    function setKeeper(address keeper_) external onlyOwner nonReentrant {
        require(keeper_ != address(0), "BaseStrategy: zero keeper");
        keeper = keeper_;
        emit KeeperSet(keeper_);
    }

    function setVault(address vault_) external onlyOwner nonReentrant {
        require(vault_ != address(0), "BaseStrategy: zero vault");
        vault = vault_;
    }

    /// @notice Return funds to the vault so it can honor user withdrawals.
    /// Callable ONLY by the vault address (set via setVault). Capped at balance.
    function recall(uint256 amount) external nonReentrant {
        require(msg.sender == vault, "BaseStrategy: not vault");
        uint256 bal = underlying.balanceOf(address(this));
        if (amount > bal) amount = bal;
        if (amount == 0) return;
        underlying.safeTransfer(vault, amount);
    }

    function setActive(bool active) external onlyOwner nonReentrant {
        isActive = active;
        emit ActiveChanged(active);
    }

    function totalAssets() public virtual view returns (uint256) {
        return underlying.balanceOf(address(this));
    }
}

contracts/DNCoreStrategy.sol.content:
// SPDX-License-Identifier: MIT
pragma solidity ^0.8.28;

import {BaseStrategy} from "./BaseStrategy.sol";
import {IERC20} from "@openzeppelin/contracts/token/ERC20/IERC20.sol";
import {IERC20Metadata} from "@openzeppelin/contracts/token/ERC20/extensions/IERC20Metadata.sol";
import {SafeERC20} from "@openzeppelin/contracts/token/ERC20/utils/SafeERC20.sol";
import {DNCoreBase} from "./adapters/DNCoreBase.sol";

/// @title DNCoreStrategy — vault-integrated delta-neutral execution on HyperCore
/// @notice The vault strategy wrapper over DNCoreBase (the shared execution
/// layer). The contract is its own HyperCore actor: it bridges USDC to Core,
/// class-transfers to perp, places the short hedge, and reads its Core equity
/// back through the read precompiles. Execution lives ONCE in DNCoreBase;
/// this contract adds the honest-accounting + vault wiring.
///
/// HONEST ACCOUNTING (repo discipline — see SkyStrategy/MorphoStrategy audits):
/// - `corePrincipal6`  = net USDC we sent to Core (never counted as yield).
/// - `coreEquity6`     = Core account value, refreshed by syncCore() reads.
/// - profit on Core    = equity - principal; only the EXCESS is realizable.
/// - `profitRealized`  = profit actually bridged back to EVM (underlying units).
/// - harvest() by the VAULT sweeps realized profit above the liquidity buffer
///   to the vault; by the keeper it only syncs (settle, no movement).
///
/// ASYNC RECALL (CoreWriter actions are fire-and-forget + delayed seconds):
/// - This contract keeps `bufferBps` of assets idle on EVM for instant vault
///   recalls (BaseStrategy.recall is vault-only, transfers idle balance).
/// - Larger recalls: keeper unwinds first (moveUsdcToSpot -> bridgeBackToEvm),
///   then the vault recalls. Documented in docs/DN_COREWRITER_ADAPTER.md.
contract DNCoreStrategy is BaseStrategy, DNCoreBase {
    using SafeERC20 for IERC20;

    /*//////////////////////// Config ////////////////////////*/
    /// @notice Scale from Core 6dp USDC to underlying token units
    /// (1 for real USDC; 1e12 for an 18-decimals test token).
    uint256 public immutable coreScale;
    uint256 public bufferBps = 1500; // liquidity buffer (bps of assets, <= 5000)
    uint256 public constant MAX_BUFFER_BPS = 5000;

    /*//////////////////////// Core accounting (6dp, Core-native) ////////////////////////*/
    int256 public coreEquity6;      // Core account value (margin summary), last sync
    uint256 public corePrincipal6;  // net USDC sent to Core (principal only)
    int64 public lastPositionSzi;   // last synced perp position size
    uint256 public lastSync;

    /*//////////////////////// Profit (underlying units) ////////////////////////*/
    uint256 public profitRealized;  // profit bridged back to EVM
    uint256 public profitSwept;     // profit already sent to the vault

    /*//////////////////////// Custom errors (EIP-170 size discipline) ////////////////////////*/
    error DNCore__DecimalsTooLow();
    error DNCore__SubDust();
    error DNCore__ExceedsBalance();
    error DNCore__ExceedsEquity();
    error DNCore__BufferTooHigh();
    error DNCore__Inactive();
    error DNCore__NotAuthorized();

    /*//////////////////////// Events (strategy-specific) ////////////////////////*/
    event BridgeToCore(uint256 evmAmount, uint64 coreAmount6);
    event BridgeToEvm(uint64 amount6, uint64 principalReduced6, uint64 profitRealized6);
    event CoreSynced(int256 equity6, int64 szi, uint256 timestamp);
    event ProfitSwept(uint256 amount);
    event BufferSet(uint256 bufferBps);

    constructor(address _underlying, address initialOwner, uint32 _perpAsset, uint256 _maxActionUsd6)
        BaseStrategy(_underlying, initialOwner, "DeltaNeutralCore")
        DNCoreBase(_perpAsset, _maxActionUsd6)
    {
        uint8 dec = IERC20Metadata(_underlying).decimals();
        if (dec < 6) revert DNCore__DecimalsTooLow();
        coreScale = 10 ** (dec - 6);
    }

    /*//////////////////////// BaseStrategy seams ////////////////////////*/
    function _keeper() internal view override returns (address) {
        return keeper; // BaseStrategy.keeper (owner-set)
    }

    /*//////////////////////// Admin ////////////////////////*/
    function setBufferBps(uint256 bufferBps_) external onlyOwner {
        if (bufferBps_ > MAX_BUFFER_BPS) revert DNCore__BufferTooHigh();
        bufferBps = bufferBps_;
        emit BufferSet(bufferBps_);
    }

    /*//////////////////////// Core account lifecycle ////////////////////////*/
    /// @notice Bridge USDC EVM->Core (lands in the contract's SPOT balance).
    /// Initializes the Core account; actions must be sent in a LATER block.
    function bridgeUsdcToCore(uint256 evmAmount) external onlyKeeper notPaused nonReentrant {
        if (evmAmount == 0) revert DNCore__ZeroAmount();
        if (evmAmount % coreScale != 0) revert DNCore__SubDust();
        if (evmAmount > underlying.balanceOf(address(this))) revert DNCore__ExceedsBalance();
        uint64 core6 = uint64(evmAmount / coreScale);
        corePrincipal6 += core6;
        emit BridgeToCore(evmAmount, core6);
        _bridgeUsdcIn(underlying, evmAmount);
    }

    /// @notice Return USDC Core->EVM (sendAsset to the USDC system address).
    /// Requires HYPE on Core for transfer gas. Splits the amount into principal
    /// vs profit at the FRESHLY-SYNCED equity: profit = amount above remaining
    /// principal. Only realized profit can ever be harvested.
    function bridgeBackToEvm(uint64 amount6) external onlyKeeper notPaused coreAccountRequired nonReentrant {
        if (amount6 == 0) revert DNCore__ZeroAmount();
        _syncCore();
        if (int256(uint256(amount6)) > coreEquity6) revert DNCore__ExceedsEquity();
        uint64 principalRed = amount6 > corePrincipal6 ? uint64(corePrincipal6) : amount6;
        uint64 profitRed = amount6 - principalRed;
        corePrincipal6 -= principalRed;
        coreEquity6 -= int256(uint256(amount6));
        if (profitRed > 0) {
            profitRealized += uint256(profitRed) * coreScale;
        }
        emit BridgeToEvm(amount6, principalRed, profitRed);
        _sendUsdcToEvm(amount6);
    }

    /*//////////////////////// Core sync (read precompiles) ////////////////////////*/
    /// @notice Refresh Core equity + position from HyperCore state. Permissionless:
    /// it only records what the precompiles report.
    function syncCore() external {
        _syncCore();
    }

    function _syncCore() internal {
        AccountMarginSummary memory m = marginSummary();
        coreEquity6 = int256(m.accountValue);
        lastPositionSzi = position().szi;
        lastSync = block.timestamp;
        emit CoreSynced(coreEquity6, lastPositionSzi, lastSync);
    }

    /// @notice Keeper-facing state snapshot.
    function coreState() external view returns (
        int256 equity6, uint256 principal6, int64 szi, uint256 realized, uint256 swept, uint256 syncedAt
    ) {
        return (coreEquity6, corePrincipal6, lastPositionSzi, profitRealized, profitSwept, lastSync);
    }

    /// @notice Strategy assets in underlying units (synced Core equity + idle).
    function totalAssets() public view override(BaseStrategy) returns (uint256) {
        uint256 eqU = coreEquity6 > 0 ? uint256(coreEquity6) * coreScale : 0;
        return eqU + underlying.balanceOf(address(this));
    }

    /// @notice Realized profit still waiting to be swept (underlying units).
    function harvestableProfit() external view returns (uint256) {
        return profitRealized > profitSwept ? profitRealized - profitSwept : 0;
    }

    /*//////////////////////// Harvest ////////////////////////*/
    /// @dev Keeper/owner: sync only (settle). Vault: sync + sweep realized
    /// profit above the liquidity buffer as REAL USDC to the vault.
    function _doHarvest() internal override returns (uint256 profit) {
        if (!isActive) revert DNCore__Inactive();
        if (msg.sender != owner() && msg.sender != keeper && msg.sender != vault) revert DNCore__NotAuthorized();
        _syncCore();
        if (msg.sender != vault) return 0; // keeper settles only; vault sweeps
        uint256 available = profitRealized > profitSwept ? profitRealized - profitSwept : 0;
        if (available == 0) return 0;
        // buffer = pct of assets kept idle for async recalls
        uint256 bal = underlying.balanceOf(address(this));
        uint256 buffer = (totalAssets() * bufferBps) / 10000;
        uint256 sweepable = bal > buffer ? bal - buffer : 0;
        uint256 sweep = available < sweepable ? available : sweepable;
        if (sweep == 0) return 0;
        profitSwept += sweep;
        underlying.safeTransfer(vault, sweep);
        emit ProfitSwept(sweep);
        return sweep; // BaseStrategy.harvest books it via totalDebt
    }
}

contracts/DeltaNeutralStrategy.sol.content:
// SPDX-License-Identifier: MIT
pragma solidity ^0.8.28;

import {BaseStrategy} from "./BaseStrategy.sol";
import {IERC20} from "@openzeppelin/contracts/token/ERC20/IERC20.sol";
import {SafeERC20} from "@openzeppelin/contracts/token/ERC20/utils/SafeERC20.sol";
import {IFundingOracle} from "./mocks/MockFundingOracle.sol";

contract DeltaNeutralStrategy is BaseStrategy {
    using SafeERC20 for IERC20;

    address public shortPosition;
    uint256 public delta;              // open position size (USDC notional)
    uint256 public fundingRate;        // last fetched annualized bps
    uint256 public lastUpdate;         // last funding fetch
    uint256 public lastAccrual;        // last funding accrual timestamp
    uint256 public accruedFunding;     // cumulative funding earned, un-swept (USDC)
    uint256 public totalPrincipal;     // USDC-notional opened across positions
    mapping(address => uint256) public positions;
    address public oracle;             // IFundingOracle — annualized bps
    address public fundingSource;      // venue settlement payer (testnet: MockFundingSource)

    uint256 public constant BPS_DENOM = 10000;
    uint256 public constant SECONDS_PER_YEAR = 365 days;

    event PositionOpened(address indexed user, uint256 size);
    event PositionClosed(address indexed user, uint256 size);
    event FundingRateUpdated(uint256 rate);
    event ShortPositionSet(address indexed short);
    event FundingSourceSet(address indexed source);
    event FundingAccrued(uint256 amount);

    constructor(address _underlying, address initialOwner, address _short, address _oracle)
        BaseStrategy(_underlying, initialOwner, "DeltaNeutral")
    {
        require(_short != address(0), "DeltaNeutral: zero short");
        require(_oracle != address(0), "DeltaNeutral: zero oracle");
        shortPosition = _short;
        oracle = _oracle;
        lastAccrual = block.timestamp;
    }

    /// @notice Accept native funding settlements from the venue (or forced sends).
    receive() external payable {}

    function name() external view override returns (string memory) {
        return "DeltaNeutral";
    }

    function setShortPosition(address short_) external onlyOwner nonReentrant {
        require(short_ != address(0), "DeltaNeutral: zero short");
        shortPosition = short_;
        emit ShortPositionSet(short_);
    }

    function setOracle(address oracle_) external onlyOwner nonReentrant {
        require(oracle_ != address(0), "DeltaNeutral: zero oracle");
        oracle = oracle_;
    }

    function setFundingSource(address source_) external onlyOwner nonReentrant {
        // slither-disable-next-line missing-zero-check
        fundingSource = source_; // address(0) intentionally disables accrual
        emit FundingSourceSet(source_);
    }

    function openPosition(uint256 size) external onlyOwner nonReentrant {
        require(size > 0, "DeltaNeutral: zero size");
        _settleAccrued(); // accrue at the old position size first
        positions[msg.sender] += size;
        delta += size;
        totalPrincipal += size;
        emit PositionOpened(msg.sender, size);
    }

    function closePosition() external onlyOwner nonReentrant {
        uint256 size = positions[msg.sender];
        require(size > 0, "DeltaNeutral: no position");
        _settleAccrued(); // accrue before shrinking
        require(delta >= size, "DeltaNeutral: underflow");
        delta -= size;
        positions[msg.sender] = 0;
        if (totalPrincipal >= size) totalPrincipal -= size;
        emit PositionClosed(msg.sender, size);
    }

    /// @notice Max annualized funding rate the strategy will ever accrue from.
    /// A broken/hostile oracle returning garbage cannot fabricate runaway
    /// yield or overflow `delta * rate * elapsed`.
    uint256 public constant MAX_RATE_BPS = 10_000; // 100% annualized

    /// @notice Fetch the live annualized funding rate from the oracle (clamped).
    function updateFunding() external onlyOwner nonReentrant {
        fundingRate = _fetchFundingRate();
        lastUpdate = block.timestamp;
        emit FundingRateUpdated(fundingRate);
    }

    function _fetchFundingRate() internal view returns (uint256) {
        if (oracle == address(0)) return 0;
        uint256 raw = IFundingOracle(oracle).getFundingRate();
        return raw > MAX_RATE_BPS ? MAX_RATE_BPS : raw; // clamp, don't revert — keeper liveness
    }

    /// @notice Accrue funding on `delta` since lastAccrual. Pays REAL USDC
    /// from the funding source into this strategy. Silent no-op while
    /// prerequisites are unset (testnet bootstrap) — never fabricates yield.
    /// slither-disable-next-line timestamp (elapsed-time accounting requires block.timestamp)
    function _settleAccrued() internal {
        uint256 elapsed = block.timestamp - lastAccrual; // compute BEFORE touching lastAccrual
        lastAccrual = block.timestamp;
        if (delta == 0 || fundingSource == address(0) || oracle == address(0)) return;
        // slither-disable-next-line incorrect-equality (zero = guard, not equality bug)
        if (fundingRate == 0 || elapsed == 0) return;
        // accrued = notional × annualRateBps × elapsed / (secondsPerYear × 10000)
        uint256 amount = (delta * fundingRate * elapsed) / (SECONDS_PER_YEAR * BPS_DENOM);
        if (amount == 0) return;
        // venue pays the accrued funding — real token movement
        // slither-disable-next-line low-level-calls (source set by owner; testnet mock in prod path)
        (bool ok, ) = fundingSource.call(
            abi.encodeWithSignature("payFunding(address,uint256)", address(this), amount)
        );
        require(ok, "DeltaNeutral: funding source failed");
        accruedFunding += amount; // effects after interaction — safe: source is trusted venue (owner-set)
        emit FundingAccrued(amount);
    }

    /// @notice Settle funding, refresh the rate, forward native ETH settlements
    /// to the short leg. When the VAULT harvests, accrued funding sweeps to it
    /// as real profit (USDC); keeper/owner harvests only settle (vault sweeps later).
    function _doHarvest() internal override returns (uint256 profit) {
        require(isActive, "DeltaNeutral: inactive");
        require(msg.sender == owner() || msg.sender == keeper || msg.sender == vault,
            "DeltaNeutral: not authorized");

        fundingRate = _fetchFundingRate();
        lastUpdate = block.timestamp;
        _settleAccrued();

        profit = 0;
        if (msg.sender == vault && accruedFunding > 0) {
            uint256 swept = accruedFunding;
            uint256 bal = underlying.balanceOf(address(this));
            if (swept > bal) swept = bal;
            if (swept > 0) {
                accruedFunding -= swept;
                underlying.safeTransfer(vault, swept);
                profit = swept; // BaseStrategy.harvest accounts it via totalDebt
            }
        }

        if (shortPosition != address(0) && isActive) {
            uint256 ethBal = address(this).balance;
            if (ethBal > 0) {
                // slither-disable-next-line arbitrary-send-eth (short set by owner)
                (bool success, ) = payable(shortPosition).call{value: ethBal}("");
                require(success, "DeltaNeutral: transfer failed");
            }
        }
    }
}

contracts/FeeDistributor.sol.content:
// SPDX-License-Identifier: MIT
pragma solidity ^0.8.28;

import {IERC20} from "@openzeppelin/contracts/token/ERC20/IERC20.sol";
import {SafeERC20} from "@openzeppelin/contracts/token/ERC20/utils/SafeERC20.sol";
import {ReentrancyGuard} from "@openzeppelin/contracts/utils/ReentrancyGuard.sol";
import {Ownable} from "@openzeppelin/contracts/access/Ownable.sol";

/// @notice Receives the vault's USDC performance fees and routes them.
/// FIX (audit 09-20): the previous version had pendingFees that nothing could
/// ever set, totalFees that decremented without ever incrementing, and a
/// distribute() that paid the CALLER — entirely non-functional. This version
/// tracks real received fees and gives the owner explicit, event-logged
/// routing (insurance fund / staking rewards / treasury). Fee recycling is a
/// deliberate owner action, never an implicit one.
contract FeeDistributor is ReentrancyGuard, Ownable {
    using SafeERC20 for IERC20;

    IERC20 public immutable usdc; // fee currency (was pyd — vault fees are USDC)
    uint256 public totalFeesReceived;
    uint256 public totalFeesRouted;

    mapping(address => uint256) public routedTo;

    event FeesReceived(uint256 amount);
    event FeesRouted(address indexed to, uint256 amount);

    constructor(address _usdc) Ownable(msg.sender) {
        require(_usdc != address(0), "FeeDistributor: zero usdc");
        usdc = IERC20(_usdc);
    }

    function name() external pure returns (string memory) {
        return "FeeDistributor";
    }

    /// @notice The vault's performance fee lands here as a plain USDC transfer
    /// (no hook). Anyone may reconcile accounting after a transfer.
    function receiveFees() external {
        uint256 bal = usdc.balanceOf(address(this));
        if (bal > totalFeesReceived) {
            totalFeesReceived = bal;
            emit FeesReceived(bal);
        }
    }

    /// @notice Route collected fees to a destination (insurance fund, staking
    /// rewards pool, treasury). Owner-only, event-logged — fee recycling is
    /// an explicit operator decision.
    function route(address to, uint256 amount) external onlyOwner nonReentrant {
        require(to != address(0), "FeeDistributor: zero to");
        uint256 bal = usdc.balanceOf(address(this));
        if (amount > bal) amount = bal;
        require(amount > 0, "FeeDistributor: nothing to route");
        usdc.safeTransfer(to, amount);
        totalFeesRouted += amount;
        routedTo[to] += amount;
        emit FeesRouted(to, amount);
    }
}

