contracts/MorphoStrategy.sol.content:
// SPDX-License-Identifier: MIT
pragma solidity ^0.8.28;

import {BaseStrategy} from "./BaseStrategy.sol";
using SafeERC20 for IERC20;
import {IERC20} from "@openzeppelin/contracts/token/ERC20/IERC20.sol";
import {SafeERC20} from "@openzeppelin/contracts/token/ERC20/utils/SafeERC20.sol";

/// @notice Morpho Blue supply strategy (principal parking — yield accrual
/// arrives with the real Morpho Blue adapter in the production pass).
/// FIX (audit 09-20): _doHarvest used to transfer the strategy's ENTIRE USDC
/// balance to `morpho` and book it as "profit" (principal drain booked as
/// yield), and withdraw() let ANY caller pull up to totalSupply of the
/// strategy's balance — bypassing vault auth. Both removed: harvest is an
/// explicit no-op until the real adapter exists, and withdrawal is
/// vault-only (mirrors BaseStrategy.recall authorization).
contract MorphoStrategy is BaseStrategy {
    address public morpho;
    uint256 public totalSupply;

    constructor(address _underlying, address initialOwner, address _morpho)
        BaseStrategy(_underlying, initialOwner, "Morpho")
    {
        require(_morpho != address(0), "Morpho: zero morpho");
        morpho = _morpho;
    }

    function name() external view override returns (string memory) {
        return "Morpho";
    }

    function setMorpho(address morpho_) external onlyOwner nonReentrant {
        require(morpho_ != address(0), "Morpho: zero morpho");
        morpho = morpho_;
    }

    /// Operator-only: park principal in the Morpho market.
    function supply(uint256 amount) external onlyOwner nonReentrant {
        require(amount > 0, "Morpho: zero amount");
        underlying.safeTransfer(morpho, amount);
        totalSupply += amount;
    }

    /// Vault-only: pull parked principal back (withdrawal liquidity path).
    /// Was PUBLIC — any caller could drain up to totalSupply (audit finding).
    function withdraw(uint256 amount) external nonReentrant {
        require(msg.sender == vault || msg.sender == owner(), "Morpho: not authorized");
        require(amount > 0, "Morpho: zero amount");
        require(totalSupply >= amount, "Morpho: insufficient supply");
        totalSupply -= amount;
        underlying.safeTransfer(msg.sender, amount);
    }

    /// No yield accrual until the production Morpho Blue adapter lands.
    /// The previous version moved PRINCIPAL to `morpho` and booked it as
    /// profit — a drain vector with fake accounting. Honest zero until real.
    function _doHarvest() internal pure override returns (uint256) {
        return 0;
    }
}

contracts/PYDFeeDiscount.sol.content:
// SPDX-License-Identifier: MIT
pragma solidity ^0.8.28;

import {IERC20} from "@openzeppelin/contracts/token/ERC20/IERC20.sol";
import {SafeERC20} from "@openzeppelin/contracts/token/ERC20/utils/SafeERC20.sol";
import {ReentrancyGuard} from "@openzeppelin/contracts/utils/ReentrancyGuard.sol";
import {Ownable} from "@openzeppelin/contracts/access/Ownable.sol";

/// @title PYDFeeDiscount — stake PYD, get your share of the fee pool back
/// @notice The PYD utility sink: tiered fee rebates mirroring Hyperliquid's
/// HYPE staking discount model, adapted to a vault with COLLECTIVE fees.
///
/// WHY A REBATE (not an execution-time discount): ProYieldVault charges the
/// performance fee on total profit and attributes NET profit pro-rata (one
/// share price, audited surface). A per-user execution-time discount would
/// require per-user share prices — a non-starter. The rebate delivers the
/// same demand driver (stake PYD → save on bigger fees) without touching the
/// vault: fees land in FeeDistributor as today, and this contract returns
/// each staker's share of them, tiered by their PYD stake.
///
/// HONEST ACCOUNTING (repo discipline):
/// - Staked PYD is NEVER yield — it is the utility position that sets your tier.
/// - Rebates accrue ONLY from real fee deltas: `snapshotHarvest()` reads the
///   USDC balance of FeeDistributor itself (public read, trust-minimized) and
///   accrues the delta since the last snapshot — no keeper-supplied numbers.
/// - Claimable rebates can never exceed the USDC budget actually routed in —
///   claim() pays what exists, keeps the remainder accrued (never fake).
/// - Stakers with zero vault shares (withdrew everything, kept the stake)
///   accrue nothing — no deposits, no fees paid, no rebate. Fair by design.
///
/// DEMAND MODEL (legal posture): a DISCOUNT on fees the user already pays —
/// not a return promise. Tiers are owner-settable; MAX_TIER_BPS hard cap.
contract PYDFeeDiscount is ReentrancyGuard, Ownable {
    using SafeERC20 for IERC20;

    IERC20 public immutable pyd;      // the utility/stake token
    IERC20 public immutable usdc;     // the rebate currency (vault fee currency)
    address public immutable feeDistributor; // where vault fees land (read-only)
    address public immutable vault;          // share weights are read from here

    /// @notice Tier schedule: [stakeThreshold, discountBps] pairs.
    /// A staker's tier = the HIGHEST threshold their stake crosses.
    uint256[][] public tiers;
    uint256 public constant MAX_TIER_BPS = 4000; // hard cap: 40% of the fee

    /*//////////////////////// Accounting ////////////////////////*/
    uint256 public lastFeeSnapshot;   // FD USDC balance at the last snapshot
    uint256 public lastSnapshotAt;
    mapping(address => uint256) public rebateOf;  // accrued-but-unclaimed (USDC 6dp)
    mapping(address => uint256) public stakedBy;  // per-user stake ledger
    address[] public stakerList;
    mapping(address => bool) public isStaker;

    /*//////////////////////// Custom errors ////////////////////////*/
    error PYDFee__ZeroAmount();
    error PYDFee__ExceedsStake();
    error PYDFee__BadTier();
    error PYDFee__NothingAccrued();
    error PYDFee__InsufficientBudget();
    error PYDFee__ZeroAddresses();

    /*//////////////////////// Events ////////////////////////*/
    event Staked(address indexed user, uint256 amount, uint256 tierBps);
    event Unstaked(address indexed user, uint256 amount);
    event SnapshotHarvested(uint256 feeDelta, uint256 totalShares, uint256 stakersAccrued);
    event RebateClaimed(address indexed user, uint256 amount);
    event TiersSet(uint256[][] tiers);
    event BudgetReceived(uint256 totalBudget);

    constructor(address _pyd, address _usdc, address _feeDistributor, address _vault, address initialOwner)
        Ownable(initialOwner)
    {
        if (_pyd == address(0) || _usdc == address(0) || _feeDistributor == address(0) || _vault == address(0)) {
            revert PYDFee__ZeroAddresses();
        }
        pyd = IERC20(_pyd);
        usdc = IERC20(_usdc);
        feeDistributor = _feeDistributor;
        vault = _vault;
        // Default tiers (mirroring HL HYPE staking, scaled for PYD):
        // ≥1,000 = 5% · ≥10K = 10% · ≥100K = 15% · ≥1M = 20% (of the fee).
        tiers = new uint256[][](4);
        tiers[0] = _tier(1_000e18, 500);
        tiers[1] = _tier(10_000e18, 1000);
        tiers[2] = _tier(100_000e18, 1500);
        tiers[3] = _tier(1_000_000e18, 2000);
    }

    function _tier(uint256 threshold, uint256 bps) internal pure returns (uint256[] memory) {
        uint256[] memory t = new uint256[](2);
        t[0] = threshold;
        t[1] = bps;
        return t;
    }

    /*//////////////////////// Admin ////////////////////////*/
    /// @dev Replace the tier schedule. Validates: strictly ascending
    /// thresholds, bps cap.
    function setTiers(uint256[][] calldata newTiers) external onlyOwner {
        if (newTiers.length == 0) revert PYDFee__BadTier();
        uint256 prevThreshold = 0;
        for (uint256 i = 0; i < newTiers.length; i++) {
            if (newTiers[i][0] <= prevThreshold) revert PYDFee__BadTier(); // must ascend
            if (newTiers[i][1] > MAX_TIER_BPS) revert PYDFee__BadTier();
            prevThreshold = newTiers[i][0];
        }
        delete tiers;
        uint256 len = newTiers.length;
        for (uint256 i = 0; i < len; i++) {
            tiers.push(newTiers[i]);
        }
        emit TiersSet(newTiers);
    }

    /*//////////////////////// Staker actions ////////////////////////*/
    /// @notice Stake PYD to raise your discount tier. Stake is NEVER yield —
    /// it only sets the tier; rebates come from real fee deltas.
    function stake(uint256 amount) external nonReentrant {
        if (amount == 0) revert PYDFee__ZeroAmount();
        pyd.safeTransferFrom(msg.sender, address(this), amount);
        stakedBy[msg.sender] += amount;
        if (!isStaker[msg.sender]) {
            isStaker[msg.sender] = true;
            stakerList.push(msg.sender);
        }
        emit Staked(msg.sender, amount, tierBpsOf(msg.sender));
    }

    function unstake(uint256 amount) external nonReentrant {
        if (amount == 0) revert PYDFee__ZeroAmount();
        if (amount > stakedBy[msg.sender]) revert PYDFee__ExceedsStake();
        stakedBy[msg.sender] -= amount;
        pyd.safeTransfer(msg.sender, amount);
        emit Unstaked(msg.sender, amount);
    }

    /// @notice Full exit: unstake everything. Accrued rebates remain claimable.
    function exit() external nonReentrant {
        uint256 staked = stakedBy[msg.sender];
        if (staked > 0) {
            stakedBy[msg.sender] = 0;
            pyd.safeTransfer(msg.sender, staked);
            emit Unstaked(msg.sender, staked);
        }
        // NOTE: stays in stakerList (zero-stake entries simply accrue 0).
    }

    /// @notice Discount tier (bps of the fee) for a staker's current stake.
    function tierBpsOf(address user) public view returns (uint256) {
        uint256 staked = stakedBy[user];
        uint256 best = 0;
        uint256 len = tiers.length;
        for (uint256 i = 0; i < len; i++) {
            if (staked >= tiers[i][0] && tiers[i][1] > best) {
                best = tiers[i][1];
            }
        }
        return best;
    }

    /*//////////////////////// Snapshot accrual (permissionless) ////////////////////////*/
    /// @notice Accrue rebates from REAL fee deltas. Permissionless: reads
    /// FeeDistributor's USDC balance and the vault's share weights itself —
    /// the caller supplies nothing. Call after each vault harvest (the keeper
    /// loop does this); calling again with no new fees is a clean no-op.
    ///
    /// rebate_i = (shares_i / totalShares) × feeDelta × tierBps_i / 10000
    /// — the staker's pro-rata share of the fee pool, scaled by their tier.
    function snapshotHarvest() external nonReentrant {
        uint256 fdBal = usdc.balanceOf(feeDistributor);
        if (fdBal <= lastFeeSnapshot) {
            // No new fees since the last snapshot — clean no-op (timestamp
            // still recorded so staleness is visible).
            lastSnapshotAt = block.timestamp;
            return;
        }
        uint256 feeDelta = fdBal - lastFeeSnapshot;
        lastFeeSnapshot = fdBal;
        lastSnapshotAt = block.timestamp;

        uint256 totalShares = _vaultTotalShares();
        if (totalShares == 0) {
            emit SnapshotHarvested(feeDelta, 0, 0);
            return;
        }

        uint256 len = stakerList.length;
        uint256 accrued = 0;
        for (uint256 i = 0; i < len; i++) {  // calls-loop: staker list only, bounded
            address staker = stakerList[i];
            uint256 shares_i = _vaultSharesOf(staker);
            if (shares_i == 0) continue; // no deposits → no fees paid → no rebate
            uint256 tierBps = tierBpsOf(staker);
            if (tierBps == 0) continue;  // staking below the first tier
            uint256 rebate = (shares_i * feeDelta * tierBps) / (totalShares * 10000);
            if (rebate > 0) {
                rebateOf[staker] += rebate;
                accrued++;
            }
        }
        emit SnapshotHarvested(feeDelta, totalShares, accrued);
    }

    /*//////////////////////// Claims ////////////////////////*/
    /// @notice Claim accrued rebates in USDC. Bounded by the budget actually
    /// routed in — never more claimable than real assets sit here.
    function claimRebate() external nonReentrant {
        uint256 amount = rebateOf[msg.sender];
        if (amount == 0) revert PYDFee__NothingAccrued();
        uint256 budget = usdc.balanceOf(address(this));
        if (amount > budget) {
            // Budget shortfall: pay what exists, keep the remainder accrued.
            amount = budget;
        }
        if (amount == 0) revert PYDFee__InsufficientBudget();
        rebateOf[msg.sender] -= amount;
        usdc.safeTransfer(msg.sender, amount);
        emit RebateClaimed(msg.sender, amount);
    }

    /// @notice Reconcile budget accounting after a plain USDC transfer (the
    /// recycler routes the discount budget here). Anyone may call.
    function receiveBudget() external {
        uint256 bal = usdc.balanceOf(address(this));
        if (bal > 0) emit BudgetReceived(bal);
    }

    /*//////////////////////// Reads (vault shares via staticcall) ////////////////////////*/
    function _vaultTotalShares() internal view returns (uint256) {
        (bool ok, bytes memory ret) = vault.staticcall(abi.encodeWithSignature("totalShares()"));
        if (!ok) return 0;
        return abi.decode(ret, (uint256));
    }

    function _vaultSharesOf(address user) internal view returns (uint256) {
        (bool ok, bytes memory ret) = vault.staticcall(abi.encodeWithSignature("shares(address)", user));
        if (!ok) return 0;
        return abi.decode(ret, (uint256));
    }

    /// @notice Accrued-but-unclaimed rebate for a staker.
    function harvestableRebate(address user) external view returns (uint256) {
        return rebateOf[user];
    }

    /// @notice Staker count (for keeper/ops visibility).
    function stakerCount() external view returns (uint256) {
        return stakerList.length;
    }
}

contracts/PYDFunder.sol.content:
// SPDX-License-Identifier: MIT
pragma solidity ^0.8.28;

import {IERC20} from "@openzeppelin/contracts/token/ERC20/IERC20.sol";
import {SafeERC20} from "@openzeppelin/contracts/token/ERC20/utils/SafeERC20.sol";
import {ReentrancyGuard} from "@openzeppelin/contracts/utils/ReentrancyGuard.sol";
import {Ownable} from "@openzeppelin/contracts/access/Ownable.sol";

/// @title PYDFunder — USDC fees → PYD reward streams (the conversion step)
/// @notice The missing link between fee/referral revenue and PYD staking:
/// collected USDC fees are converted into PYD and streamed to PYDStaking as
/// reward windows — automatically, in capped slices, without any APY promise.
///
/// WHY THIS EXISTS (the honest-fee discipline): PYDStaking.fundRewards needs
/// PYD. Today fees arrive as USDC and nothing converts them — referral
/// revenue, vault perf fees and recycling income pile up in FeeDistributor
/// with no path to PYD demand. This contract closes that loop: the owner/
/// keeper routes USDC in (from the FD recycle), and `topUp()` converts up to
/// `maxConvertUsd6` per call into PYD via a configurable swapper, then funds
/// a stream on PYDStaking.
///
/// WHY A SWAPPER INTERFACE (not a hardcoded router): the DEX landscape isn't
/// decided (HyperEVM AMM vs HyperCore spot). The swapper is a separate,
/// minimal contract the owner sets — this keeps THIS contract's audit surface
/// tiny and lets the swap venue evolve without redeploying.
///
/// HONEST ACCOUNTING:
/// - Never promises APY: the stream size is whatever the conversion yielded.
/// - Every conversion is event-logged (USDC in, PYD out, stream funded).
/// - `maxConvertUsd6` caps per-call exposure; `minConvertUsd6` skips dust.
/// - The owner can pause; all state changes precede external calls.
contract PYDFunder is ReentrancyGuard, Ownable {
    using SafeERC20 for IERC20;

    IERC20 public immutable usdc;
    IPYDStaking public immutable staking;
    ISwapper public swapper; // set by owner; swaps USDC -> PYD

    uint256 public maxConvertUsd6 = 1000e6;  // per-call cap
    uint256 public minConvertUsd6 = 10e6;    // dust skip
    bool public paused;

    error PYDFunder__ZeroAmount();
    error PYDFunder__BelowDust();
    error PYDFunder__Cap();
    error PYDFunder__ZeroAddresses();
    error PYDFunder__Paused();
    error PYDFunder__ZeroSwapper();
    error PYDFunder__NoOutput();

    event UsdcReceived(uint256 total);
    event Converted(address indexed swapper, uint256 usdcIn, uint256 pydOut);
    event StreamFunded(uint256 pydAmount, uint256 duration);
    event MaxConvertSet(uint256 cap);
    event PausedSet(bool paused);
    event SwapperSet(address indexed swapper);

    constructor(address _usdc, address _staking, address initialOwner) Ownable(initialOwner) {
        if (_usdc == address(0) || _staking == address(0)) revert PYDFunder__ZeroAddresses();
        usdc = IERC20(_usdc);
        staking = IPYDStaking(_staking);
    }

    /*//////////////////////// Admin ////////////////////////*/
    function setSwapper(address s) external onlyOwner {
        if (s == address(0)) revert PYDFunder__ZeroSwapper();
        swapper = ISwapper(s);
        emit SwapperSet(s);
    }

    function setMaxConvertUsd6(uint256 cap) external onlyOwner {
        maxConvertUsd6 = cap;
        emit MaxConvertSet(cap);
    }

    function setPaused(bool p) external onlyOwner {
        paused = p;
        emit PausedSet(p);
    }

    /// @notice Setup: the staking owner transfers PYDStaking ownership to
    /// this contract (OZ v5 Ownable is one-step: transferOwnership IS final)
    /// so `topUp` can fund reward streams directly. Without this,
    /// fundRewards (onlyOwner) would revert for the funder.

    /*//////////////////////// Reconciliation ////////////////////////*/
    /// @notice Track USDC routed in from the recycler/FD (plain transfers).
    /// Anyone may call — mirrors FD.receiveFees.
    function receiveUsdc() external {
        uint256 bal = usdc.balanceOf(address(this));
        if (bal > 0) emit UsdcReceived(bal);
    }

    /*//////////////////////// Conversion + stream funding ////////////////////////*/
    /// @notice Convert up to `amount6` USDC into PYD and fund a reward stream.
    /// Permissionless above the dust floor (keeper work is liveness, not
    /// trust): the caps + swapper hold policy.
    ///
    /// Flow: USDC -> swapper -> PYD -> staking.fundRewards(pyd, duration).
    /// The stream size is whatever the swap yielded — never a modeled number.
    function topUp(uint256 amount6, uint256 duration) external nonReentrant {
        if (paused) revert PYDFunder__Paused();
        if (address(swapper) == address(0)) revert PYDFunder__ZeroSwapper();
        if (amount6 == 0) revert PYDFunder__ZeroAmount();
        if (amount6 < minConvertUsd6) revert PYDFunder__BelowDust();
        uint256 cap = amount6 > maxConvertUsd6 ? maxConvertUsd6 : amount6;

        uint256 balance = usdc.balanceOf(address(this));
        if (cap > balance) cap = balance;
        if (cap < minConvertUsd6) revert PYDFunder__BelowDust();

        // 1) Approve + swap. Output is verified by BALANCE DELTA (the return
        // value is advisory — a malicious swapper can lie; balances can't).
        usdc.forceApprove(address(swapper), cap);
        uint256 pydBefore = IERC20(staking.pyd()).balanceOf(address(this));
        uint256 pydOut = 0;
        // Effects-before-interactions discipline: events emit before the
        // external call (tx atomicity keeps ordering equivalent).
        emit Converted(address(swapper), cap, 0);
        uint256 got = swapper.swap(address(usdc), address(staking.pyd()), cap, 0);
        pydOut = IERC20(staking.pyd()).balanceOf(address(this)) - pydBefore;
        if (pydOut == 0) revert PYDFunder__NoOutput();
        // Revoke the allowance IMMEDIATELY after the swap — the swapper must
        // never hold a live approval on this contract's USDC.
        usdc.forceApprove(address(swapper), 0);

        // 2) Fund the stream (staking pulls PYD from this contract)
        IERC20(staking.pyd()).forceApprove(address(staking), pydOut);
        staking.fundRewards(pydOut, duration);

        emit StreamFunded(pydOut, duration);
    }

    /// @notice Convenience read: how much USDC is awaiting conversion.
    function pendingUsdc() external view returns (uint256) {
        return usdc.balanceOf(address(this));
    }
}

/*//////////////////////// Minimal interfaces ////////////////////////*/
interface IPYDStaking {
    function pyd() external view returns (address);
    function fundRewards(uint256 amount, uint256 duration) external;
}

/// @dev Minimal swap interface — the owner-set swapper implements this.
/// `minOut=0` is acceptable HERE because the output is verified by balance
/// delta and the stream size is whatever arrived (no modeled expectation to
/// violate). A production swapper should still enforce its own slippage.
interface ISwapper {
    function swap(address tokenIn, address tokenOut, uint256 amountIn, uint256 minOut) external returns (uint256);
}

contracts/PYDStaking.sol.content:
// SPDX-License-Identifier: MIT
pragma solidity ^0.8.28;

import {IERC20} from "@openzeppelin/contracts/token/ERC20/IERC20.sol";
import {SafeERC20} from "@openzeppelin/contracts/token/ERC20/utils/SafeERC20.sol";
import {Ownable} from "@openzeppelin/contracts/access/Ownable.sol";
import {ReentrancyGuard} from "@openzeppelin/contracts/utils/ReentrancyGuard.sol";

/// @notice PYD staking with time-based reward accrual (Synthetix-style).
/// FIX (audit 09-20): the previous getReward() paid stakeAmount x REWARD_RATE
/// — 100x the staker's own deposit, from a contract holding only 1x — an
/// instant revert DoS. Rewards now accrue per-second, pro-rata by stake, from
/// an explicitly funded reward pool; users can never claim more than exists.
contract PYDStaking is Ownable, ReentrancyGuard {
    using SafeERC20 for IERC20;

    IERC20 public immutable pyd;

    mapping(address => uint256) public stakeAmount;
    mapping(address => uint256) public userRewardPerTokenPaid;
    mapping(address => uint256) public rewards;
    uint256 public totalSupply;

    uint256 public rewardRate;          // PYD per second across all stakers
    uint256 public rewardsDuration;     // seconds the current rate runs
    uint256 public periodFinish;        // timestamp current rate ends
    uint256 public lastUpdateTime;
    uint256 public rewardPerTokenStored;

    event Stake(address indexed user, uint256 amount);
    event Withdraw(address indexed user, uint256 amount);
    event Reward(address indexed user, uint256 amount);
    event RewardsFunded(uint256 amount, uint256 duration);

    constructor(address _pyd) Ownable(msg.sender) {
        require(_pyd != address(0), "PYDStaking: zero pyd");
        pyd = IERC20(_pyd);
        lastUpdateTime = block.timestamp;
    }

    function name() external pure returns (string memory) {
        return "PYDStaking";
    }

    // ── Operator: fund the reward pool ──────────────────────────────
    function fundRewards(uint256 amount, uint256 duration) external onlyOwner nonReentrant {
        require(amount > 0 && duration > 0, "PYDStaking: zero");
        // Bank every reward accrued so far at the OLD rate BEFORE any window
        // mutation. Without this, resetting lastUpdateTime below silently
        // ERASES all accrual since the last user interaction (found by the
        // mid-period top-up test: 33k PYD vanished).
        //
        // ORDER MATTERS: _updatePeriod() FIRST — it banks the expired window's
        // final stretch exactly once (and zeroes the old rate); the following
        // _rewardPerToken() is then a no-op in that case, and only banks
        // accrual-to-now for mid-period top-ups. The reversed order
        // double-counted the whole tail of an expired window whenever
        // fundRewards ran after a lapse with NO user interaction in between —
        // rewards became claimable beyond the funded pool, eating staked
        // principal (caught by the foundry invariant suite: fundRewards after
        // lapse → balance < totalSupply).
        _updatePeriod();
        rewardPerTokenStored = _rewardPerToken();
        if (block.timestamp >= periodFinish) {
            rewardRate = amount / duration;
        } else {
            // mid-period top-up: unspent remainder rolls into the new window
            uint256 remaining = periodFinish - block.timestamp;
            uint256 leftover = remaining * rewardRate;
            rewardRate = (amount + leftover) / duration;
        }
        rewardsDuration = duration;
        periodFinish = block.timestamp + duration;
        lastUpdateTime = block.timestamp;
        pyd.safeTransferFrom(msg.sender, address(this), amount);
        emit RewardsFunded(amount, duration);
    }

    // ── Staker actions ──────────────────────────────────────────────
    function stake(uint256 amount) external nonReentrant {
        require(amount > 0, "PYDStaking: amount is 0");
        _updatePeriod();
        _updateReward(msg.sender);
        pyd.safeTransferFrom(msg.sender, address(this), amount);
        stakeAmount[msg.sender] += amount;
        totalSupply += amount;
        emit Stake(msg.sender, amount);
    }

    function withdraw(uint256 amount) external nonReentrant {
        require(amount > 0, "PYDStaking: amount is 0");
        _updatePeriod();
        _updateReward(msg.sender);
        require(stakeAmount[msg.sender] >= amount, "PYDStaking: insufficient stake");
        stakeAmount[msg.sender] -= amount;
        totalSupply -= amount;
        pyd.safeTransfer(msg.sender, amount);
        emit Withdraw(msg.sender, amount);
    }

    function getReward() external nonReentrant {
        _updatePeriod();
        _updateReward(msg.sender);
        uint256 reward = rewards[msg.sender];
        if (reward > 0) {
            // pool always holds staked + funded rewards; never over-pays
            rewards[msg.sender] = 0;
            pyd.safeTransfer(msg.sender, reward);
            emit Reward(msg.sender, reward);
        }
    }

    /// Compound exit: principal + rewards in one tx. Inlined (NOT this.withdraw/
    /// this.getReward — external self-call makes msg.sender the contract itself,
    /// breaking every msg.sender-keyed lookup).
    function exit() external nonReentrant {
        _updatePeriod();
        _updateReward(msg.sender);
        uint256 amt = stakeAmount[msg.sender];
        if (amt > 0) {
            stakeAmount[msg.sender] = 0;
            totalSupply -= amt;
            pyd.safeTransfer(msg.sender, amt);
            emit Withdraw(msg.sender, amt);
        }
        uint256 reward = rewards[msg.sender];
        if (reward > 0) {
            rewards[msg.sender] = 0;
            pyd.safeTransfer(msg.sender, reward);
            emit Reward(msg.sender, reward);
        }
    }

    // ── Views ───────────────────────────────────────────────────────
    function earned(address account) external view returns (uint256) {
        return rewards[account] + (stakeAmount[account] * (_rewardPerToken() - userRewardPerTokenPaid[account])) / 1e18;
    }

    // ── Internals ───────────────────────────────────────────────────
    function _rewardPerToken() internal view returns (uint256) {
        if (totalSupply == 0) return rewardPerTokenStored;
        uint256 lastApplicable = block.timestamp < periodFinish ? block.timestamp : periodFinish;
        if (lastApplicable <= lastUpdateTime) return rewardPerTokenStored;
        return rewardPerTokenStored
            + ((lastApplicable - lastUpdateTime) * rewardRate * 1e18) / totalSupply;
    }

    function _updatePeriod() internal {
        if (block.timestamp >= periodFinish && periodFinish > 0) {
            // Bank the FINAL stretch (lastUpdateTime -> periodFinish) BEFORE
            // zeroing the rate. Zeroing first erased the unbanked tail for any
            // claim made after periodFinish (found by the staggered-join test:
            // a 4-day window — 40k PYD — silently lost). Idempotent: a second
            // call with lastUpdateTime == periodFinish returns stored.
            rewardPerTokenStored = _rewardPerToken();
            lastUpdateTime = periodFinish;
            rewardRate = 0; // no further accrual past the funded window
        }
    }

    function _updateReward(address account) internal {
        rewardPerTokenStored = _rewardPerToken();
        lastUpdateTime = lastT();
        rewards[account] += (stakeAmount[account] * (rewardPerTokenStored - userRewardPerTokenPaid[account])) / 1e18;
        userRewardPerTokenPaid[account] = rewardPerTokenStored;
    }

    function lastT() internal view returns (uint256) {
        return block.timestamp < periodFinish ? block.timestamp : periodFinish;
    }
}

contracts/PYDToken.sol.content:
// SPDX-License-Identifier: MIT
pragma solidity ^0.8.28;

import {Ownable} from "@openzeppelin/contracts/access/Ownable.sol";

contract PYDToken is Ownable {
    string public constant name = "ProYield";
    string public constant symbol = "PYD";
    uint8 public constant decimals = 18;
    uint256 public immutable totalSupply;
    mapping(address => uint256) public balanceOf;
    mapping(address => mapping(address => uint256)) public allowance;

    constructor(uint256 _initialSupply) Ownable(msg.sender) {
        totalSupply = _initialSupply * 10**18;
        balanceOf[msg.sender] = totalSupply;
    }

    function transfer(address to, uint256 value) external returns (bool) {
        require(balanceOf[msg.sender] >= value, "Insufficient balance");
        balanceOf[msg.sender] -= value;
        balanceOf[to] += value;
        return true;
    }

    function approve(address spender, uint256 value) external returns (bool) {
        allowance[msg.sender][spender] = value;
        return true;
    }

    function transferFrom(address from, address to, uint256 value) external returns (bool) {
        require(balanceOf[from] >= value, "Insufficient balance");
        require(allowance[from][msg.sender] >= value, "Allowance exceeded");
        balanceOf[from] -= value;
        balanceOf[to] += value;
        allowance[from][msg.sender] -= value;
        return true;
    }
}

contracts/PendleStrategy.sol.content:
// SPDX-License-Identifier: MIT
pragma solidity ^0.8.28;

import {BaseStrategy} from "./BaseStrategy.sol";
using SafeERC20 for IERC20;
import {IERC20} from "@openzeppelin/contracts/token/ERC20/IERC20.sol";
import {SafeERC20} from "@openzeppelin/contracts/token/ERC20/utils/SafeERC20.sol";

contract PendleStrategy is BaseStrategy {
    address public pendleMarket;
    uint256 public immutable maturity;

    constructor(address _underlying, address initialOwner, address _pendleMarket)
        BaseStrategy(_underlying, initialOwner, "Pendle")
    {
        require(_pendleMarket != address(0), "Pendle: zero market");
        pendleMarket = _pendleMarket;
        maturity = block.timestamp + 365 days;
    }

    function name() external view override returns (string memory) {
        return "Pendle";
    }

    /// @notice Accept native venue settlements (mirrors DeltaNeutral). Without
    /// this, _claimRewards's `address(this).balance > 0` branch was UNREACHABLE
    /// dead code — found by the round-4 post-maturity claim test.
    receive() external payable {}

    function setMarket(address market) external onlyOwner nonReentrant {
        require(market != address(0), "Pendle: zero market");
        pendleMarket = market;
    }

    function harvest() external override nonReentrant {
        if (block.timestamp > maturity && pendleMarket != address(0)) {
            _claimRewards();
        }
    }

    /// @notice BUGFIX (found by time-warp integration test): this was marked
    /// nonReentrant while its ONLY caller (harvest) also holds the lock —
    /// after maturity every harvest reverted with ReentrancyGuardReentrantCall,
    /// bricking the whole vault harvest for a year. Internal-only helper:
    /// the entry-point lock is sufficient. Auth extended to the vault so
    /// ProYieldVault.harvest's sweep loop can claim on behalf of depositors.
    function _claimRewards() internal {
        if (address(this).balance > 0 && (msg.sender == owner() || msg.sender == vault)) {
            // slither-disable-next-line low-level-calls
            (bool success, ) = pendleMarket.call{value: address(this).balance}("");
            require(success, "Pendle: transfer failed");
        }
    }

}

contracts/ProYieldVault.sol.content:
// SPDX-License-Identifier: MIT
pragma solidity ^0.8.28;

import {BaseStrategy} from "./BaseStrategy.sol";
import {IERC20} from "@openzeppelin/contracts/token/ERC20/IERC20.sol";
import {SafeERC20} from "@openzeppelin/contracts/token/ERC20/utils/SafeERC20.sol";

contract ProYieldVault is BaseStrategy {
    using SafeERC20 for IERC20;
    uint256 public performanceFee;
    uint256 public immutable withdrawalFee;
    uint256 public constant RESERVE_BPS = 1000; // 10% of assets kept liquid for withdrawals
    address public immutable feeDistributor;
    mapping(address => bool) public strategies;
    event PerformanceFeeSet(uint256 fee);
    mapping(address => bool) public strategyActive;   // per-strategy circuit breaker
    event StrategyHarvestFailed(address indexed strategy);
    // ── Beta safety rails (S2 unlock plan): hard limits live in code, not policy.
    // Caps are owner-set; 0 = uncapped. The pause blocks NEW deposits only —
    // withdrawals always stay open so users are never trapped.
    uint256 public tvlCap;         // max totalAssets() in asset units
    uint256 public perUserCap;     // max per-user VALUE in asset units (value, not principal)
    bool public depositsPaused;
    event CapsSet(uint256 tvlCap, uint256 perUserCap);
    event DepositsPausedSet(bool paused);
    uint256 private _totalAssets;
    uint256 private _totalShares;                     // sum of all user shares (ERC-4626 style)
    address[] public strategyList;
    // Virtual share offset (OpenZeppelin ERC4626 pattern): blunts first-depositor
    // inflation attacks by requiring huge donations to move the share price.
    uint256 private constant SHARE_OFFSET = 1e3;

    constructor(
        address _underlying,
        address initialOwner,
        address _feeDistributor
    ) BaseStrategy(_underlying, initialOwner, "ProYieldVault") {
        require(_feeDistributor != address(0), "ProYieldVault: zero feeDistributor");
        require(_underlying != address(0), "ProYieldVault: zero underlying");
        require(initialOwner != address(0), "ProYieldVault: zero owner");
        feeDistributor = _feeDistributor;
        performanceFee = 1000;
        withdrawalFee = 0; // product promise: NO withdrawal fees (kept for future gating)
    }

    function name() external view override returns (string memory) {
        return "ProYieldVault";
    }

    function totalAssets() public override view returns (uint256) {
        return _totalAssets;
    }

    function totalShares() external view returns (uint256) {
        return _totalShares;
    }

    /// Shares for a given asset amount at the current price (floor).
    function convertToShares(uint256 assets) external view returns (uint256) {
        return _toShares(assets);
    }

    /// Asset value of a share amount at the current price (floor).
    function convertToAssets(uint256 sharesAmt) external view returns (uint256) {
        return _toAssets(sharesAmt); // named sharesAmt — does not shadow BaseStrategy.shares
    }

    /// Max assets `account` can withdraw right now (frontend helper).
    function maxWithdraw(address account) external view returns (uint256) {
        return _toAssets(shares[account]);
    }

    function _toShares(uint256 assets) internal view returns (uint256) {
        if (_totalShares == 0) return assets; // first depositor: 1:1
        return (assets * (_totalShares + SHARE_OFFSET)) / (_totalAssets + SHARE_OFFSET);
    }

    function _toAssets(uint256 sharesAmt) internal view returns (uint256) {
        if (_totalShares == 0) return sharesAmt;
        return (sharesAmt * (_totalAssets + SHARE_OFFSET)) / (_totalShares + SHARE_OFFSET);
    }

    function addStrategy(address strategy) external onlyOwner {
        require(strategy != address(0), "ProYieldVault: zero strategy");
        strategies[strategy] = true;
        strategyActive[strategy] = true;   // new strategies start active
        strategyList.push(strategy);
    }

    /// @notice Quarantine one strategy without stopping the whole vault.
    /// Inactive strategies are skipped by allocate() and cannot be harvested into.
    function setStrategyActive(address strategy, bool active) external onlyOwner {
        require(strategies[strategy], "ProYieldVault: not a strategy");
        strategyActive[strategy] = active;
    }

    /// @notice Set the beta safety rails. 0 = uncapped; takes effect immediately.
    function setCaps(uint256 _tvlCap, uint256 _perUserCap) external onlyOwner {
        tvlCap = _tvlCap;
        perUserCap = _perUserCap;
        emit CapsSet(_tvlCap, _perUserCap);
    }

    /// @notice Pause/unpause NEW deposits (withdrawals stay open by design).
    function setDepositsPaused(bool paused) external onlyOwner {
        depositsPaused = paused;
        emit DepositsPausedSet(paused);
    }

    function deposit(uint256 amount) external override nonReentrant {
        require(!depositsPaused, "ProYieldVault: deposits paused");
        require(amount > 0, "ProYieldVault: zero amount");
        if (tvlCap > 0) {
            require(_totalAssets + amount <= tvlCap, "ProYieldVault: TVL cap reached");
        }
        if (perUserCap > 0) {
            require(_toAssets(shares[msg.sender]) + amount <= perUserCap, "ProYieldVault: per-user cap reached");
        }
        uint256 sh = _toShares(amount); // price-aware mint (4626-style)
        require(sh > 0, "ProYieldVault: zero shares"); // dust guard — no free deposits
        shares[msg.sender] += sh;
        _totalShares += sh;
        _totalAssets += amount;
        underlying.safeTransferFrom(msg.sender, address(this), amount);
        emit Deposit(msg.sender, amount);
    }

    function setPerformanceFee(uint256 fee) external onlyOwner {
        require(fee <= 10000, "ProYieldVault: fee too high");
        performanceFee = fee;
        emit PerformanceFeeSet(fee);
    }

    function emergencyWithdraw() external onlyOwner nonReentrant {
        uint256 balance = underlying.balanceOf(address(this));
        if (balance == 0) return;
        underlying.safeTransfer(msg.sender, balance);
        // Keep liabilities in sync: assets leaving the vault must shrink
        // totalAssets or depositor claims exceed real backing (T-012 follow-up).
        _totalAssets -= balance;
    }

    function allocate() external onlyOwner nonReentrant {
        uint256 balance = underlying.balanceOf(address(this));
        // Keep a liquid reserve so withdrawals never depend on strategy recall.
        uint256 reserve = (_totalAssets * RESERVE_BPS) / 10000;
        uint256 deployable = balance > reserve ? balance - reserve : 0;
        if (deployable > 0 && strategyList.length > 0) {
            // Split only across ACTIVE strategies; inactive ones get nothing.
            uint256 activeCount = 0;
            for (uint i = 0; i < strategyList.length; i++) {
                if (strategies[strategyList[i]] && strategyActive[strategyList[i]]) {
                    activeCount++;
                }
            }
            if (activeCount == 0) return;
            uint256 perStrategy = deployable / activeCount;
            for (uint i = 0; i < strategyList.length; i++) {
                address strategy = strategyList[i];
                if (strategies[strategy] && strategyActive[strategy] && perStrategy > 0) {
                    underlying.safeTransfer(strategy, perStrategy);
                }
            }
        }
    }

    /// @notice Pull funds back from strategies until `needed` is idle.
    /// Splits the shortfall across active strategies; recall is capped at each
    /// strategy's balance, so a shortfall larger than total recalled reverts
    /// downstream (correct behavior — cannot pay out assets that don't exist).
    function _recallShortfall(uint256 needed) internal {
        uint256 idle = underlying.balanceOf(address(this));
        if (idle >= needed) return;
        uint256 missing = needed - idle;
        uint256 activeCount = 0;
        for (uint i = 0; i < strategyList.length; i++) {
            if (strategies[strategyList[i]] && strategyActive[strategyList[i]]) {
                activeCount++;
            }
        }
        if (activeCount == 0) return; // withdraw will revert on insufficient idle
        uint256 perStrategy = (missing / activeCount) + 1; // round up
        for (uint i = 0; i < strategyList.length && missing > 0; i++) {
            address strategy = strategyList[i];
            if (strategies[strategy] && strategyActive[strategy]) {
                BaseStrategy(strategy).recall(perStrategy);
                uint256 got = underlying.balanceOf(address(this)) - idle;
                idle += got;
                missing = got >= missing ? 0 : missing - got;
            }
        }
    }

    /// @notice User withdrawal by ASSET amount. Shares burned are computed at
    /// the current price (4626-style): when the vault has earned profit, a
    /// user's shares redeem for MORE than they deposited.
    /// Pays from idle; recalls from strategies to cover any shortfall.
    function withdraw(uint256 amount) external nonReentrant {
        require(amount > 0, "ProYieldVault: zero amount");
        require(amount <= totalAssets(), "ProYieldVault: exceeds assets");
        uint256 sh = _toShares(amount);
        require(sh > 0, "ProYieldVault: zero shares");
        require(sh <= shares[msg.sender], "ProYieldVault: exceeds shares");
        // Effects BEFORE interactions (slither reentrancy-no-eth): burn shares
        // and shrink liabilities before any external recall call.
        shares[msg.sender] -= sh;
        _totalShares -= sh;
        _totalAssets -= amount;
        _recallShortfall(amount);
        underlying.safeTransfer(msg.sender, amount);
        emit Withdraw(msg.sender, amount);
    }

    function harvest() external override nonReentrant {
        // Sweep accrued profit from every active strategy, then take the
        // performance fee on what actually landed (no modeled yield).
        uint256 idleBefore = underlying.balanceOf(address(this));
        uint256 len = strategyList.length;
        for (uint256 i = 0; i < len; i++) {  // calls-loop: vault-authorized strategies only
            address s = strategyList[i];
            if (strategies[s] && strategyActive[s]) {
                // Resilient sweep: ONE broken strategy must never brick the
                // whole vault's harvest (profits of healthy strategies would
                // strand, keeper loops, fee loop stalls). Skip + emit; the
                // strategy stays visible for ops/owner intervention.
                try BaseStrategy(s).harvest() {
                } catch {
                    emit StrategyHarvestFailed(s);
                }
            }
        }
        uint256 totalProfit = underlying.balanceOf(address(this)) - idleBefore;
        if (totalProfit > 0 && performanceFee > 0) {
            uint256 fee = (totalProfit * performanceFee) / 10000;
            if (fee > 0) underlying.safeTransfer(feeDistributor, fee);
        }
        // Profit attribution (4626-style): NET profit (after fee) raises the
        // share price — every depositor earns pro-rata. Fees leave accounting.
        if (totalProfit > _feeOn(totalProfit)) {
            _totalAssets += totalProfit - _feeOn(totalProfit);
        }
        lastHarvest = block.timestamp;
        emit Harvest(totalProfit);
    }

    /// Fee mirror of harvest's calculation (internal, avoids duplication).
    function _feeOn(uint256 profit) internal view returns (uint256) {
        if (performanceFee == 0) return 0;
        return (profit * performanceFee) / 10000;
    }

    /// @notice Credit EXTERNAL yield (fee recycling, rebates, grants) to
    /// depositors by raising the share price. Flow: the recycler routes X
    /// USDC into this vault (FeeDistributor.route), then calls creditYield(X).
    /// The balance check makes crediting more than actually sits in the vault
    /// impossible; the recycler's route+credit pairing keeps accounting ==
    /// real assets (credit only NEW arrivals, never re-count idle).
    event YieldCredited(uint256 amount);

    function creditYield(uint256 amount) external onlyOwner nonReentrant {
        require(amount > 0, "ProYieldVault: zero amount");
        require(underlying.balanceOf(address(this)) >= amount, "ProYieldVault: exceeds balance");
        _totalAssets += amount;
        emit YieldCredited(amount);
    }

    function harvestStrategy(address strategy) external onlyOwner nonReentrant {
        require(strategies[strategy], "ProYieldVault: not a strategy");
        require(strategyActive[strategy], "ProYieldVault: strategy paused");
        require(strategy != address(0), "ProYieldVault: zero strategy");
        BaseStrategy(strategy).harvest();
    }
}

